-- Schema and seed data for lift_pass.db (SQLite).
-- To rebuild the database:  sqlite3 lift_pass.db < initDatabase.sql
--
-- holidays: the resort's own winter holidays plus 18,937 real national and regional
-- public holidays (1970-2070) from 35 European countries, generated with the Python
-- 'holidays' library. One row per date; the description lists the countries.
-- Test dates 2019-02-11, 2019-02-12 and 2019-02-23 are intentionally kept free of holidays.

BEGIN TRANSACTION;

DROP TABLE IF EXISTS base_price;
DROP TABLE IF EXISTS holidays;

CREATE TABLE base_price (
    pass_id INTEGER PRIMARY KEY AUTOINCREMENT,
    type    TEXT    NOT NULL UNIQUE,
    cost    INTEGER NOT NULL
);


CREATE TABLE holidays (
    holiday     DATE NOT NULL PRIMARY KEY, -- stored as 'yyyy-MM-dd' text
    description TEXT NOT NULL
);



COMMIT;
